mapper.select:
SELECT id, operation_type, operation_business, operation_object, user_name, remark, create_time AS operationTime, user_id, menu_id, login_name FROM bp_operation_log WHERE is_deleted = 0
and (user_name like concat('%',#{userName},'%') or login_name like concat('%',#{userName},'%'))
and create_time between #{startTimeDate} and #{endTimeDate}
and menu_id like concat(#{menuId},'%')
and operation_type = #{operationType}
order by create_time desc

SELECT id, operation_type, operation_business, operation_object, user_name, user_id, remark, create_time, menu_id FROM bp_operation_log WHERE is_deleted = 0 and id in
#{id}
order by create_time desc
